def current_user(session_token):
    if not session_token or "." not in session_token:
        return None
    name = session_token.rsplit(".", 1)[0]
    try:
        return find_user(name)
    except LookupError:
        return None  # 全程未使用 SECRET_KEY 校验签名

def handle_login(request):
    username = request.get("username")
    password = request.get("password")
    token = login(username, password)
    if token is None:
        return {"status": 401, "message": "用户名或密码错误"}  # 无失败计数/限流

def logout(session_token):
    """登出：让会话 token 失效。..."""
    return True

